defineEmits<{ 'update:mode': [value: QuotationMode]; 'update:skuSearch': [value: string]; 'update:customerName': [value: string]; 'update:productCategory': [value: string]; 'update:monthlySalesEstimate': [value: string]; query: []; 'update:logisticsAttribute': [value: string]; 'update:grade': [value: string] }>()
</script>

<template>
  <section class="condition-card">
    <header><div><b><i>01</i> 报价条件</b><span>系统自动匹配采购成本，并在报价矩阵中生成可用渠道</span></div><p><span>当前报价业务员</span><strong>{{ salesperson }}</strong><em>登录账号自动带出</em></p></header>
    <div class="condition-grid" :class="{ bundle: mode === 'bundle' }">
      <label class="customer-field" data-validation-field="customerName" :class="{ invalid:invalidFields.includes('customerName') }"><span>客户名称 <em>保存必填</em></span><input :value="customerName" placeholder="输入客户名称" @input="$emit('update:customerName', ($event.target as HTMLInputElement).value)"><small v-if="invalidFields.includes('customerName')" class="field-error">请填写客户名称</small></label>
      <label class="mode-field"><span>报价模式</span><select :value="mode" @change="$emit('update:mode', ($event.target as HTMLSelectElement).value as QuotationMode)"><option value="single">单品 SKU 报价</option><option value="bundle">组合 SKU 报价</option></select></label>
      <label v-if="mode === 'single'" class="sku-field" data-validation-field="sku" :class="{ invalid:invalidFields.includes('sku') }"><span>SKU</span><div class="sku-input"><i>⌕</i><input :value="skuSearch" placeholder="输入 SKU" @input="$emit('update:skuSearch', ($event.target as HTMLInputElement).value)" @keyup.enter="$emit('query')"></div><small v-if="invalidFields.includes('sku')" class="field-error">请输入并查询有效 SKU</small></label>
      <label class="logistics-field"><span>物流属性</span><select :value="logisticsAttribute" @change="$emit('update:logisticsAttribute', ($event.target as HTMLSelectElement).value)"><option v-for="attribute in attributes" :key="attribute">{{ attribute }}</option></select></label>
      <label class="grade-field"><span>客户等级</span><select :value="grade" @change="$emit('update:grade', ($event.target as HTMLSelectElement).value)"><option v-for="setting in grades" :key="setting.grade" :value="setting.grade">{{ setting.grade }}级客户</option></select><small>报价系数 {{ coefficient.toFixed(2) }}</small></label>
      <label class="category-field" data-validation-field="productCategory" :class="{ invalid:invalidFields.includes('productCategory') }"><span>产品品类 <em>保存必填</em></span><select :value="productCategory" @change="$emit('update:productCategory', ($event.target as HTMLSelectElement).value)"><option value="" disabled>请选择产品品类</option><option v-for="category in productCategories" :key="category" :value="category">{{ category }}</option></select><small v-if="invalidFields.includes('productCategory')" class="field-error">请选择产品品类</small></label>
