    </div>
    <footer><span>{{ mode === 'bundle' ? '在组合明细中逐个查询 SKU，物流属性由本次组合统一选择。' : '查询后将刷新商品成本、重量及下方渠道报价矩阵。' }}</span><button v-if="mode === 'single'" @click="$emit('query')">查询商品</button></footer>
  </section>
